import{_ as t,o as d,c as o,a0 as r}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md"}'),a={name:"reference/api.md"};function s(i,e,c,n,h,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>The node serves REST + SSE under <code>/api/*</code>. <code>peregrin</code> (the CLI) and <code>peregrin-hub</code> both consume this surface — everything the UI can do is on this wire.</p><h2 id="identity-and-health" tabindex="-1">Identity and health <a class="header-anchor" href="#identity-and-health" aria-label="Permalink to &quot;Identity and health&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/health</code></td><td>Liveness + store readability</td></tr><tr><td><code>GET /api/node</code></td><td>Node identity, agents, capabilities</td></tr><tr><td><code>PATCH /api/node</code></td><td>Rename the node (persisted to <code>PEREGRIN_NODE</code>)</td></tr><tr><td><code>GET /api/user</code></td><td>OS user the node runs as</td></tr><tr><td><code>GET /api/agents</code></td><td>Agent runtimes registered on the plane</td></tr><tr><td><code>GET /api/fs</code></td><td>Subdirectory listing for a path</td></tr><tr><td><code>GET /api/events</code></td><td>SSE feed — session/meta/project/heartbeat</td></tr><tr><td><code>POST /api/pair</code></td><td>Redeem a pair code for a bearer token</td></tr></tbody></table><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/sessions</code></td><td>Merged list (<code>?locks=1</code> probes live holders)</td></tr><tr><td><code>GET /api/sessions/:id</code></td><td>Session detail or summary</td></tr><tr><td><code>GET /api/sessions/:id/history</code></td><td>Paginated history</td></tr><tr><td><code>GET /api/sessions/:id/export</code></td><td>Session IR JSON</td></tr><tr><td><code>POST /api/sessions</code></td><td>Create (<code>cwd</code>, <code>agent</code>, <code>title</code>, <code>model</code>)</td></tr><tr><td><code>POST /api/sessions/import</code></td><td>Import IR or <code>history</code> array → store</td></tr><tr><td><code>POST /api/sessions/:id/prompt</code></td><td>Send a turn to an attached session</td></tr><tr><td><code>POST /api/sessions/:id/attach</code></td><td>Attach (<code>takeover</code> preempts live holder)</td></tr><tr><td><code>POST /api/sessions/:id/detach</code></td><td>Release a held session</td></tr><tr><td><code>POST /api/sessions/:id/cancel</code></td><td>Cancel a running turn</td></tr><tr><td><code>POST /api/sessions/:id/permission</code></td><td>Resolve a permission request</td></tr><tr><td><code>POST /api/sessions/:id/convert</code></td><td>Copy into another agent&#39;s store</td></tr><tr><td><code>DELETE /api/sessions/:id</code></td><td>Delete from the owning store</td></tr><tr><td><code>PATCH /api/sessions/:id</code></td><td>Rename / pin / archive (overlay meta)</td></tr></tbody></table><h2 id="projects-and-config" tabindex="-1">Projects and config <a class="header-anchor" href="#projects-and-config" aria-label="Permalink to &quot;Projects and config&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/projects</code></td><td>Node-local project grouping of sessions</td></tr><tr><td><code>GET /api/config</code></td><td>Agent config IR (rules, skills, hooks, MCP)</td></tr></tbody></table><h2 id="auth-and-errors" tabindex="-1">Auth and errors <a class="header-anchor" href="#auth-and-errors" aria-label="Permalink to &quot;Auth and errors&quot;">​</a></h2><p>Non-loopback nodes require <code>Authorization: Bearer &lt;PEREGRIN_TOKEN&gt;</code>. Errors are JSON <code>{ &quot;code&quot;, &quot;message&quot;, &quot;cause&quot; }</code> mirroring <code>ControlErrorCode</code> — <code>not_found</code>, <code>locked</code> (a live holder blocks the op; pass <code>takeover</code>), <code>invalid_params</code>, <code>internal</code>.</p>',10)])])}const T=t(a,[["render",s]]);export{u as __pageData,T as default};
